    use codex_app_server_protocol::McpToolCallStatus;
    use codex_core::protocol::McpToolCallEndEvent;
    use mcp_types::CallToolResult;

    // Determine status based on presence of error or result
    let (status, result, error) = if let Some(err) = end_event.error {
        (McpToolCallStatus::Failed, None, Some(McpToolCallError { message: err }))
    } else if let Some(result_data) = end_event.result {
        // Convert mcp_types::CallToolResult to our internal McpToolCallResult
        let content = result_data
            .content
            .iter()
            .map(|cb| {
                use mcp_types::ContentBlock;
                match cb {
                    ContentBlock::Text(t) => codex_app_server_protocol::McpContentBlock::Text(t.clone()),
                    ContentBlock::Image(i) => codex_app_server_protocol::McpContentBlock::Image(i.clone()),
                    ContentBlock::Resource(r) => codex_app_server_protocol::McpContentBlock::Resource(r.clone()),
                }
            })
            .collect();
        let structured_content = result_data.structured_content.clone();
        (McpToolCallStatus::Completed, Some(McpToolCallResult { content, structured_content }), None)
    } else {
        // Fallback if neither error nor result is present, treat as failed or completed with empty
        // Based on typical patterns, if no result and no error, it might be an edge case, 
        // but often implies completion with empty content. Let's assume Completed with empty result.
