pub(crate) async fn send_prompt(
        &self,
        agent_id: ThreadId,
        prompt: String,
    ) -> CodexResult<String> 
{
    let manager = self.upgrade()?;

    // Acquire the lock to access the thread registry
    let registry = manager.registry.read().await;

    // Check if the thread exists
    let thread_entry = registry.get(&agent_id).ok_or_else(|| {
        CodexErr::ThreadNotFound(agent_id)
    })?;

    // Send the prompt via the thread's input channel
    let mut input_sender = thread_entry.input_sender.clone();

    // Construct the UserInput item
    let user_input = UserInput::Text {
        text: prompt,
        text_elements: Vec::new(),
    };

    // Construct the Op::UserInput message
    let op = Op::UserInput {
        items: vec![user_input],
        final_output_json_schema: None,
    };

    // Send the operation to the agent
    input_sender.send(op).await.map_err(|_| {
        CodexErr::InternalAgentDied
    })?;

    // Return an empty string as success indicator (as per signature returning String)
    Ok(String::new())
