    if let Ok(cwd_buf) = resolved_cwd.try_into() {
        if !writable_roots.iter().any(|p| p.as_path() == resolved_cwd) {
            writable_roots.push(cwd_buf);
        }
    }

    let policy = SandboxPolicy::WorkspaceWrite {
        writable_roots,
        network_access: workspace_config.network_access,
        exclude_tmpdir_env_var: workspace_config.exclude_tmpdir_env_var,
        exclude_slash_tmp: workspace_config.exclude_slash_tmp,
    };

