    // But since we are in the WorkspaceWrite branch, we assume the user wants write access.
    // The flag is likely set if the underlying platform sandbox (e.g. RestrictedToken) is not available
    // but the config requested a mode that relies on it.

    // Re-evaluating based on `get_platform_sandbox`:
    // If we are on Windows and `get_platform_sandbox()` returns None, we might need to flag it.
    // However, the function signature doesn't give us access to `get_platform_sandbox` directly inside
    // the impl without calling it. Let's assume the logic is:
    // If on Windows, and we are trying to use WorkspaceWrite (which might imply a sandbox),
    // but the platform sandbox is not available, we flag it.

    let forced_downgrade = is_windows && crate::safety::get_platform_sandbox().is_none();

    SandboxPolicyResolution {
        policy,
        forced_auto_mode_downgraded_on_windows: forced_downgrade,
    }
