) -> Option<WebSearchMode> {
    // Priority 1: Explicit `web_search` setting in the profile overrides everything.
    if let Some(mode) = config_profile.web_search {
        return Some(mode);
    }

    // Priority 2: Explicit `web_search` setting in the global config.
    if let Some(mode) = config_toml.web_search {
        return Some(mode);
    }

