pub async fn collect_git_info(cwd: &Path) -> Option<GitInfo> {
    // Check if the directory is a git repository by looking for .git
    if !cwd.join(".git").exists() {
        return None;
    }

    // Define the timeout duration (e.g., 5 seconds)
    const GIT_COMMAND_TIMEOUT: TokioDuration = TokioDuration::from_secs(5);

    // Helper to run git commands with timeout
    async fn run_git_command_with_timeout(args: &[&str], cwd: &Path) -> Option<std::process::Output> {
        let result = timeout(
            GIT_COMMAND_TIMEOUT,
            Command::new("git").args(args).current_dir(cwd).output(),
        )
        .await;

        match result {
            Ok(Ok(output)) => Some(output),
            _ => None, // Timeout or error
        }
    }

    // Helper to parse string from output
    fn parse_output(output: Option<std::process::Output>) -> Option<String> {
        output
            .and_then(|o| {
                if o.status.success() {
                    String::from_utf8(o.stdout).ok()
                } else {
                    None
                }
            })
            .map(|s| s.trim().to_string())
    }

    // Run all git commands in parallel
    let commit_hash_task = {
        let cwd = cwd.to_path_buf();
        tokio::spawn(async move {
            run_git_command_with_timeout(&["rev-parse", "--verify", "HEAD"], &cwd).await
        })
    };

    let branch_task = {
        let cwd = cwd.to_path_buf();
        tokio::spawn(async move {
            run_git_command_with_timeout(&["rev-parse", "--abbrev-ref", "HEAD"], &cwd).await
        })
    };

    let remote_url_task = {
        let cwd = cwd.to_path_buf();
        tokio::spawn(async move {
            run_git_command_with_timeout(&["remote", "get-url", "origin"], &cwd).await
        })
    };

    let (commit_output, branch_output, remote_output) =
        tokio::join!(commit_hash_task, branch_task, remote_url_task);

    // Parse outputs
    let commit_hash = parse_output(commit_output.ok()?.await.ok().flatten());
    let branch = parse_output(branch_output.ok()?.await.ok().flatten());
    let repository_url = parse_output(remote_output.ok()?.await.ok().flatten());

    // Only return GitInfo if at least commit_hash is present
    if commit_hash.is_none() {
        return None;
    }

    Some(GitInfo {
        commit_hash,
        branch,
        repository_url,
    })
}

