pub fn skills_for_config(&self, config: &Config) -> SkillLoadOutcome {
    let cwd = config.cwd.clone();

    // Check if we already have a cached result for this cwd
    {
        let cache_guard = self.cache_by_cwd.read().unwrap();
        if let Some(cached) = cache_guard.get(&cwd) {
            return cached.clone();
        }
    }

    // Load system skills first
    let mut outcome = install_system_skills();

    // Load skills from the config layer stack
    let skill_roots = skill_roots_from_layer_stack(&config.config_layer_stack);
    let loaded = load_skills_from_roots(skill_roots);

    // Merge the loaded skills into the outcome
    outcome.skills.extend(loaded.skills);

    // Update the cache
    {
        let mut cache_guard = self.cache_by_cwd.write().unwrap();
        cache_guard.insert(cwd, outcome.clone());
    }

    outcome
