pub fn new_workspace_write_policy() -> Self {
    use std::env;
    use std::path::PathBuf;

    let cwd = env::current_dir()
        .map(AbsolutePathBuf::from)
        .unwrap_or_else(|_| AbsolutePathBuf::from(PathBuf::from(".")));

    let mut writable_roots = vec![cwd];

    // On macOS (and generally Unix), include the per-user TMPDIR if present
    if let Ok(tmpdir) = env::var("TMPDIR") {
        if !tmpdir.is_empty() {
            writable_roots.push(AbsolutePathBuf::from(PathBuf::from(tmpdir)));
        }
    } else {
        // Fallback to /tmp on Unix-like systems if TMPDIR is not set
        #[cfg(unix)]
        {
            writable_roots.push(AbsolutePathBuf::from(PathBuf::from("/tmp")));
        }
    }

    SandboxPolicy::WorkspaceWrite {
        writable_roots,
        network_access: false,
        exclude_tmpdir_env_var: false,
        exclude_slash_tmp: false,
    }
}

