pub fn insert_history_lines<B>(
    terminal: &mut crate::custom_terminal::Terminal<B>,
    lines: Vec<Line>,
) -> io::Result<()>
where
    B: Backend + Write,
{
    use crossterm::cursor::{Hide, Show};
    use crossterm::terminal::{Clear, ClearType};

    let viewport = terminal.viewport_area;
    let mut history_lines = lines;

    // Wrap lines to fit the viewport width
    let width = viewport.width as usize;
    if width > 0 {
        history_lines = crate::wrapping::word_wrap_lines_borrowed(&history_lines, width);
    }

    // Calculate total lines to insert
    let history_height = history_lines.len() as u16;
    if history_height == 0 {
        return Ok(());
    }

    // Ensure we have enough vertical space
    let total_height = terminal.last_known_screen_size.height;
    let viewport_height = viewport.height;

    // Determine the new scroll region
    let scroll_start = 0;
    let scroll_end = total_height - 1;

    // Hide cursor during update
    queue!(terminal.backend, Hide)?;

    // Set up scroll region to cover the entire screen except the viewport area at the bottom
    // We want to scroll the content above the viewport
    let scroll_region_start = 0;
    let scroll_region_end = (total_height - viewport_height).saturating_sub(1);

    if scroll_region_end >= scroll_region_start {
        queue!(terminal.backend, crossterm::terminal::SetScrollRegion(scroll_region_start..=scroll_region_end))?;
    }

    // Clear the area where history will be inserted
    // This area is from row 0 to row (total_height - viewport_height)
    let clear_start_row = 0;
    let clear_end_row = (total_height - viewport_height).saturating_sub(1);
    let clear_width = width as u16;

    // Move cursor to the top-left of the clear area
    queue!(terminal.backend, crossterm::cursor::MoveTo(0, clear_start_row))?;

    // Clear the region line by line
    for row in clear_start_row..=clear_end_row {
        queue!(terminal.backend, crossterm::cursor::MoveTo(0, row), Clear(ClearType::UntilNewLine))?;
    }

    // Write history lines starting from the top
