pub fn insert_history_lines<B>(
    terminal: &mut crate::custom_terminal::Terminal<B>,
    lines: Vec<Line>,
) -> io::Result<()>
where
    B: Backend + Write,
{
    use crossterm::cursor::MoveTo;
    use crossterm::queue;
    use ratatui::layout::Rect;
    use ratatui::text::Line;

    let viewport_area = terminal.viewport_area;
    let screen_size = terminal.last_known_screen_size;

    // Calculate the new viewport position (shifted down by the number of lines to insert)
    let lines_count = lines.len();
    if lines_count == 0 {
        return Ok(());
    }

    // The new viewport starts below the inserted lines
    let new_y = viewport_area.top() as u16 + lines_count as u16;
    let new_height = viewport_area.height;

    // Check if the new viewport fits within the screen
    if new_y + new_height > screen_size.height {
        // If it doesn't fit, we can't simply insert; we might need to adjust or truncate.
        // For this implementation, we clamp the new height to fit.
        let remaining_height = screen_size.height - new_y;
        if remaining_height == 0 {
            // No space to insert, return early or handle as needed.
            return Ok(());
        }
    }

    // Define the scroll region: from the new viewport top to the bottom of the screen
    // This allows us to scroll the existing content down.
    let scroll_top = new_y;
    let scroll_bottom = screen_size.height;

    // Set the scroll region
    let scroll_region = SetScrollRegion((scroll_top..scroll_bottom).into());
    queue!(&mut terminal.backend, scroll_region)?;

    // Move the cursor to the top of the viewport (where the new lines will start)
    // Actually, we need to move to the top of the *new* viewport area to start printing
    // but first we need to clear the lines we are about to write.

    // Clear the lines that will be overwritten by the new history (the area we are inserting into)
    // We clear from new_y to new_y + lines_count
    for i in 0..lines_count {
        let row = new_y + i;
        // Clear the entire row
        queue!(
            &mut terminal.backend,
            MoveTo(0, row),
            Clear(crossterm::terminal::ClearType::UntilNewLine)
        )?;
    }

    // Now, we need to move the existing viewport content down.
    // The crossterm scroll command works by scrolling the defined region.
    // We defined the region from new_y to bottom.
    // We need to scroll it down by lines_count.
    // crossterm's ScrollDown command scrolls the region down, pushing content out the bottom.
    use crossterm::cursor::ScrollDown;
    queue!(
        &mut terminal.backend,
        ScrollDown(lines_count as u16)
    )?;

    // Reset the scroll region to default (0 to screen height)
    queue!(&mut terminal.backend, ResetScrollRegion)?;

    // Now print the new lines at the top of the viewport area (which is now visually where the history starts)
    // The viewport area effectively moved down in our logic, but the physical screen area from new_y to new_y+lines_count
    // is now empty and ready for the new lines.

    // Calculate the effective viewport for the new lines
    let history_area = Rect {
        x: viewport_area.x,
        y: viewport_area.y,
        width: viewport_area.width,
        height: lines_count as u16,
    };

    // Render the lines into the history area
    // We need to wrap lines to fit the width
    let width = history_area.width;
    let wrapped_lines = word_wrap_lines_borrowed(lines.iter(), width);

    // Write the wrapped lines to the terminal at the top of the viewport area
    // Note: The viewport_area.y is the original top. We are writing starting there.
    let mut current_y = viewport_area.y;

    for line in wrapped_lines {
        if current_y >= viewport_area.y + history_area.height {
            break; // Should not happen if logic is correct, but safety check
        }

        queue!(
            &mut terminal.backend,
            MoveTo(viewport_area.x as u16, current_y)
        )?;

        write_spans(&mut terminal.backend, line.spans.iter())?;

        current_y += 1;
    }

    // Update the terminal's viewport_area to reflect the new position
    // The viewport is now lower by lines_count
    terminal.viewport_area.y += lines_count as u16;
    // Ensure the height doesn't exceed screen bounds
    if terminal.viewport_area.y + terminal.viewport_area.height > screen_size.height {
        terminal.viewport_area.height = screen_size.height - terminal.viewport_area.y;
    }

    // Flush the backend
    terminal.backend.flush()?;

    Ok(())
}

