    if selection.is_empty() {
        return;
    }

    let start = selection.start();
    let end = selection.end();

    // Map content-relative line indices to viewport-relative indices.
    let viewport_start_line = start.line.saturating_sub(self.transcript_view_top);
    let viewport_end_line = end.line.saturating_sub(self.transcript_view_top);

    // Determine the horizontal offset based on the gutter columns.
    let gutter_width = TRANSCRIPT_GUTTER_COLS as u16;
    let content_start_x = gutter_width;

    // Ensure the selection is within the visible area.
    if viewport_start_line >= area.height as usize || viewport_end_line >= area.height as usize {
        return;
    }

    // Clamp column indices to the area width.
    let start_col = start.column as u16;
    let end_col = end.column as u16;

    let start_x = content_start_x + start_col;
    let end_x = content_start_x + end_col;

    // Ensure coordinates are within the buffer bounds.
    let start_y = viewport_start_line as u16;
    let end_y = viewport_end_line as u16;

    if start_x >= area.width || end_x >= area.width {
        return;
    }

    // Apply the selection style to the buffer.
    for y in start_y..=end_y {
        let y_offset = y;
        let line_start = if y == start_y { start_x } else { content_start_x };
        let line_end = if y == end_y { end_x } else { area.width.saturating_sub(1) };

        for x in line_start..=line_end {
            if let Some(cell) = buf.get_mut(area.x + x, area.y + y_offset) {
                cell.style = cell.style.bg(ratatui::style::Color::DarkGray);
            }
        }
    }
}
