fn apply_transcript_selection(&self, area: Rect, buf: &mut Buffer) {
    if let TranscriptSelection::Some(start, end) = &self.transcript_selection {
        // Map content-relative line indices to viewport-relative line indices.
        let viewport_start_line = start.line.saturating_sub(self.transcript_view_top);
        let viewport_end_line = end.line.saturating_sub(self.transcript_view_top);

        // Ensure the selection is within the visible viewport and buffer bounds.
        if viewport_start_line >= area.height as usize {
            return;
        }

        let mut y = viewport_start_line as u16;
        let mut x = start.col.min(area.width);

        // Apply selection style to the starting character.
        if y < area.height && x < area.width {
            if let Some(cell) = buf.get_mut(area.x + x, area.y + y) {
                cell.style = cell.style.fg(ratatui::style::Color::Blue);
            }
        }

        // Handle multi-character selections on the same line.
        if start.line == end.line {
            let end_x = end.col.min(area.width);
            for col in (x + 1)..end_x {
                if y < area.height && col < area.width {
                    if let Some(cell) = buf.get_mut(area.x + col, area.y + y) {
                        cell.style = cell.style.fg(ratatui::style::Color::Blue);
                    }
                }
            }
            return;
        }

        // Fill the rest of the start line.
        let line_width = area.width;
        for col in (x + 1)..line_width {
            if y < area.height {
                if let Some(cell) = buf.get_mut(area.x + col, area.y + y) {
                    cell.style = cell.style.fg(ratatui::style::Color::Blue);
                }
            }
        }

        // Move to the next line and fill intermediate lines.
        y += 1;
        while y < viewport_end_line as u16 && y < area.height {
            for col in 0..area.width {
                if let Some(cell) = buf.get_mut(area.x + col, area.y + y) {
                    cell.style = cell.style.fg(ratatui::style::Color::Blue);
                }
            }
            y += 1;
        }

        // Fill the end line up to the end column.
        if y < area.height {
            let end_x = end.col.min(area.width);
            for col in 0..end_x {
                if let Some(cell) = buf.get_mut(area.x + col, area.y + y) {
                    cell.style = cell.style.fg(ratatui::style::Color::Blue);
                }
            }
        }
    }
