    let label_number = self.attached_images.len() + 1;
    let placeholder = local_image_label_text(label_number);
    let attached_image = AttachedImage {
        placeholder: placeholder.clone(),
        path,
    };
    self.attached_images.push(attached_image);

    // Insert the placeholder at the current cursor position in the textarea
    let current_text = self.textarea.text().to_string();
    let cursor_pos = self.textarea.cursor();
    let (before, after) = current_text.split_at(cursor_pos);
    let new_text = format!("{}{} {}", before, placeholder, after);
    let new_cursor_pos = cursor_pos + placeholder.len();

    self.textarea.set_text(new_text);
    self.textarea.set_cursor(new_cursor_pos);
}
