pub fn handle_key_event(&mut self, key_event: KeyEvent) -> (InputResult, bool) {
    // If the event is a release, ignore it.
    if key_event.kind != KeyEventKind::Press {
        return (InputResult::None, false);
    }

    // If input is disabled (e.g., during sandbox setup), ignore all events except Esc.
    if !self.input_enabled {
        if key_event.code == KeyCode::Esc {
            // Allow Esc to potentially change footer mode even when disabled
            let next_mode = esc_hint_mode(self.footer_mode, self.is_task_running);
            if next_mode != self.footer_mode {
                self.footer_mode = next_mode;
                return (InputResult::None, true);
            }
        }
        return (InputResult::None, true);
    }

    // Handle global shortcuts (like quit) that override everything.
    if self.handle_shortcut_overlay_key(&key_event) {
        return (InputResult::None, true);
    }

    // Route to the appropriate handler based on the active popup state.
    match self.active_popup {
        ActivePopup::Command(_) => self.handle_key_event_with_slash_popup(key_event),
        ActivePopup::File(_) => self.handle_key_event_with_file_popup(key_event),
        ActivePopup::Skill(_) => self.handle_key_event_with_skill_popup(key_event),
        ActivePopup::None => self.handle_key_event_without_popup(key_event),
