pub fn insert_history_lines<B>(
    terminal: &mut crate::custom_terminal::Terminal<B>,
    lines: Vec<Line>,
) -> io::Result<()>
where
    B: Backend + Write,
{
    use crossterm::cursor::MoveTo;
    use crossterm::queue;
    use crossterm::style::Color as CColor;
    use crossterm::style::SetAttribute;
    use crossterm::terminal::Clear;
    use crossterm::terminal::ClearType;
    use ratatui::backend::Backend;
    use ratatui::buffer::Buffer;
    use ratatui::layout::Rect;
    use ratatui::text::Line;
    use ratatui::text::Span;
    use ratatui::style::Style;
    use ratatui::style::Modifier;
    use std::io::Write;

    // Calculate the height of lines to insert after wrapping
    let viewport_width = terminal.viewport_area.width;
    let wrapped_lines: Vec<Line> = crate::wrapping::word_wrap_lines_borrowed(lines, viewport_width);
    let insert_height = wrapped_lines.len() as u16;

    // Ensure we don't insert more lines than the terminal height allows
    if insert_height == 0 {
        return Ok(());
    }

    let terminal_height = terminal.last_known_screen_size.height;
    if insert_height >= terminal_height {
        // If lines fill the entire screen, just clear and redraw everything
        terminal.backend.clear()?;
        terminal.backend.queue(MoveTo(0, 0))?;

        let mut buffer = Buffer::empty(Rect {
            x: 0,
            y: 0,
            width: terminal.last_known_screen_size.width,
            height: terminal.last_known_screen_size.height,
        });

        for (y, line) in wrapped_lines.iter().enumerate() {
            if y >= terminal_height as usize {
                break;
            }
            for (x, span) in line.spans.iter().enumerate() {
                if (x as u16) < terminal.last_known_screen_size.width {
                    buffer[(x as u16, y as u16)] = buffer[(x as u16, y as u16)]
                        .set_symbol(&span.content)
                        .set_style(span.style);
                }
            }
        }

        terminal.backend.draw(&buffer)?;
        return Ok(());
    }

    // Set scroll region to exclude the area where new lines will be inserted
    // Scroll region: from insert_height to end of terminal
    let scroll_start = insert_height;
    let scroll_end = terminal_height - 1;

    // Define scroll region command
    struct SetScrollRegion(pub std::ops::Range<u16>);
    impl crossterm::Command for SetScrollRegion {
        fn write_ansi(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "\x1b[{};{}r", self.0.start, self.0.end)
        }
    }

    // Move cursor to the start of the area to be scrolled
    queue!(terminal.backend, MoveTo(0, scroll_start))?;

    // Set the scroll region
    queue!(terminal.backend, SetScrollRegion(scroll_start..=scroll_end))?;

    // Insert lines by scrolling down and clearing the new area
    // First, move cursor to the top of the insert area
    queue!(terminal.backend, MoveTo(0, 0))?;

    // Clear the area where new lines will appear
    for _ in 0..insert_height {
        queue!(terminal.backend, Clear(ClearType::CurrentLine))?;
    }

    // Move cursor to the top of the insert area to start writing
    queue!(terminal.backend, MoveTo(0, 0))?;

    // Write the wrapped lines
    for (y, line) in wrapped_lines.iter().enumerate() {
        if (y as u16) >= terminal_height {
            break;
        }

        // Move to the correct line
        queue!(terminal.backend, MoveTo(0, y as u16))?;

        // Write the line content
        write_spans(&mut terminal.backend, line.spans.iter())?;
    }

    // Reset scroll region
    queue!(terminal.backend, SetScrollRegion(0..=terminal_height - 1))?;

    // Move cursor to the original viewport position
    let viewport_start_y = terminal.viewport_area.y;
    queue!(terminal.backend, MoveTo(terminal.viewport_area.x, viewport_start_y))?;

    Ok(())
}

