                // The first wrapped segment corresponds to the original input line, so we use the
                // cell-provided joiner (hard break vs soft break *between input lines*).
                out.joiner_before.push(
                    rendered
                        .joiner_before
                        .get(base_idx)
                        .cloned()
                        .unwrap_or(None),
                );
