    cells: &[Arc<dyn HistoryCell>],
    width: u16,
) -> TranscriptLines {
    if width == 0 {
        return TranscriptLines {
            lines: Vec::new(),
            meta: Vec::new(),
            joiner_before: Vec::new(),
        };
